205: function readDnaBank() {
206:   try {
207:     const parsed = JSON.parse(localStorage.getItem(DNA_BANK_KEY) || "[]");
208:     if (!Array.isArray(parsed)) return [];
209:     return parsed.filter((entry) => entry && typeof entry.id === "string" &&
210:       typeof entry.name === "string" && entry.genome &&
211:       GENE_KEYS.every((key) => Number.isFinite(entry.genome[key]) && entry.genome[key] >= 0 && entry.genome[key] <= 1));
212:   } catch {
213:     return [];
214:   }
215: }
