217: function writeDnaBank(entries) {
218:   try {
219:     localStorage.setItem(DNA_BANK_KEY, JSON.stringify(entries.slice(0, DNA_BANK_LIMIT)));
220:     return true;
221:   } catch {
222:     showToast("Archive unavailable", "Browser storage is full or disabled", "!", 3200);
223:     return false;
224:   }
225: }
