290: function restoreGenome(id) {
291:   const entry = readDnaBank().find((item) => item.id === id);
292:   const org = currentOrganism();
293:   if (!entry || !org) return;
294:   org.genome = Object.fromEntries(GENE_KEYS.map((key) => [key, entry.genome[key]]));
295:   org.evaluation = evaluate(org.genome, state.env, org.condition);
296:   org.origin = "DNA bank";
