389:   const name = nameCreature(org.genome);
390:   const color = creatureColorHex(creature);
391:   els.panel.style.setProperty("--specimen-color", color);
392:   els.specimenGlyph.style.setProperty("--specimen-color", color);
393:   const hslColor = new THREE.Color(color);
394:   const hsl = {};
395:   hslColor.getHSL(hsl);
396:   els.specimenLatin.style.color = `hsl(${Math.round(hsl.h * 360)}, 28%, 58%)`;
397: 
398:   const cellular = state.stage === "cellular";
399:   els.specimenId.textContent = `${cellular ? "CELL" : "SPECIMEN"} K-${pad(creatures.selectedIndex + 1)}`;
400:   els.specimenName.textContent = name.common;
401:   els.specimenLatin.textContent = cellular ? `cellular lineage · ${name.latin}` : name.latin;
402:   els.dossierHeading.textContent = cellular ? "Cell dossier" : "Specimen dossier";
403:   els.traitHeading.textContent = cellular ? "Cellular gene expression" : "Trait expression";
404:   els.stageNote.textContent = cellular
405:     ? "Cellular stage · membrane-bound cell with nucleus, nucleolus, mitochondria & ribosomes"
406:     : "Organism stage · multicellular form with differentiated body systems";
407:   els.diet.textContent = cellular ? "Eukaryote" : org.genome.armor > 0.66 ? "Omnivore" : org.genome.neck > 0.62 ? "Browser" : "Grazer";
408:   els.plan.textContent = cellular ? "Single cell" : org.genome.legs > 0.66 ? "Cursorial" : "Quadruped";
409:   els.creatureTagName.textContent = name.common;
410:   els.creatureTagMeta.textContent = `${cellular ? "cell" : "specimen"} K-${pad(creatures.selectedIndex + 1)} · fitness ${Math.round(org.evaluation.fitness)}`;
411: 
412:   const fitness = org.evaluation.fitness;
413:   const ringColor = fitnessColor(fitness);
414:   const deg = fitness * 3.6;
415:   els.fitnessRing.style.background = `conic-gradient(${ringColor} 0deg ${deg}deg, rgba(255,255,255,0.07) ${deg}deg 360deg)`;
416:   els.fitnessRing.style.setProperty("--ring-color", ringColor);
417:   els.specimenFitness.textContent = Math.round(fitness);
418:   els.specimenFitness.style.color = ringColor;
419:   els.fitThermal.textContent = Math.round(org.evaluation.components.thermal);
420:   els.fitForage.textContent = Math.round(org.evaluation.components.foraging);
421:   els.fitDefense.textContent = Math.round(org.evaluation.components.defense);
422:   els.fitEnergy.textContent = Math.round(org.evaluation.components.efficiency);
423: 
424:   const status = fitness >= 72 ? "Thriving" : fitness >= 56 ? "Stable" : "Stressed";
425:   els.status.textContent = status;
426:   els.status.style.color = fitness >= 56 ? "var(--mint)" : "var(--coral)";
427:   const weightValues = org.evaluation.weights;
428:   const weightTotal = Object.values(weightValues).reduce((sum, value) => sum + value, 0);
429:   for (const key of ["thermal", "foraging", "defense", "efficiency"]) {
430:     const percentage = (weightValues[key] / weightTotal) * 100;
431:     els.weights[key][0].style.width = `${percentage}%`;
432:     els.weights[key][1].textContent = `${Math.round(percentage)}%`;
433:   }
434: 
435:   const targets = traitTargets(state.env);
436:   const rows = [...els.traitList.querySelectorAll(".trait")];
437:   for (const row of rows) {
438:     const key = row.dataset.gene;
439:     const raw = org.genome[key];
440:     row.querySelector("[data-value]").textContent = traitDisplay(key, raw);
441:     row.querySelector("[data-fill]").style.width = `${clamp(raw, 0, 1) * 100}%`;
442:     const optimum = row.querySelector("[data-optimum]");
443:     optimum.style.left = `${clamp(targets[key] ?? 0.5, 0.02, 0.98) * 100}%`;
444:   }
445: 
446:   els.mutagenPips.innerHTML = Array.from({ length: 5 }, (_, i) => `<i class="${i < state.mutagen ? "full" : ""}"></i>`).join("");
447:   els.btnMutate.disabled = state.mutagen <= 0;
448:   renderPopDots();
449: }
