482: function drawChart() {
483:   const canvas = els.chart;
484:   const ctx = canvas.getContext("2d");
485:   const width = canvas.width;
486:   const height = canvas.height;
487:   ctx.clearRect(0, 0, width, height);
488: 
489:   const values = state.history.slice(-20);
490:   const min = 28;
491:   const max = 96;
492:   const padX = 5;
493:   const padY = 13;
494: 
495:   ctx.save();
496:   ctx.strokeStyle = "rgba(180, 255, 220, 0.08)";
497:   ctx.lineWidth = 1;
498:   ctx.setLineDash([3, 7]);
499:   for (let i = 0; i < 4; i += 1) {
500:     const y = padY + ((height - padY * 2) / 3) * i;
501:     ctx.beginPath();
502:     ctx.moveTo(0, y);
503:     ctx.lineTo(width, y);
504:     ctx.stroke();
505:   }
506:   ctx.restore();
507: 
508:   if (!values.length) return;
509: 
510:   const graphValues = values.length === 1 ? [values[0], values[0]] : values;
511:   const getY = (value) => padY + (1 - (clamp(value, min, max) - min) / (max - min)) * (height - padY * 2);
512:   const getX = (index) => padX + (index / (graphValues.length - 1)) * (width - padX * 2);
513: 
514:   const points = graphValues.map((value, index) => ({ x: getX(index), y: getY(value) }));
515: 
516:   ctx.beginPath();
517:   ctx.moveTo(points[0].x, height);
518:   ctx.lineTo(points[0].x, points[0].y);
519:   for (let i = 1; i < points.length; i += 1) {
520:     const prev = points[i - 1];
521:     const point = points[i];
522:     const midX = (prev.x + point.x) / 2;
523:     ctx.bezierCurveTo(midX, prev.y, midX, point.y, point.x, point.y);
524:   }
525:   ctx.lineTo(points[points.length - 1].x, height);
526:   ctx.closePath();
527:   const fill = ctx.createLinearGradient(0, 0, 0, height);
528:   fill.addColorStop(0, "rgba(201, 255, 102, 0.2)");
529:   fill.addColorStop(1, "rgba(201, 255, 102, 0)");
530:   ctx.fillStyle = fill;
531:   ctx.fill();
532: 
533:   ctx.beginPath();
534:   ctx.moveTo(points[0].x, points[0].y);
535:   for (let i = 1; i < points.length; i += 1) {
536:     const prev = points[i - 1];
537:     const point = points[i];
538:     const midX = (prev.x + point.x) / 2;
