40:     ctx.fillStyle = `rgba(${shade}, ${shade}, ${shade - 8}, ${0.04 + rng() * 0.14})`;
41:     ctx.beginPath();
42:     ctx.arc(x, y, radius, 0, Math.PI * 2);
43:     ctx.fill();
44:   }
45:   for (let i = 0; i < 170; i += 1) {
46:     const x = rng() * size;
47:     const y = rng() * size;
48:     ctx.strokeStyle = `rgba(55, 55, 48, ${0.03 + rng() * 0.09})`;
49:     ctx.lineWidth = 0.5 + rng() * 1.6;
50:     ctx.beginPath();
51:     ctx.moveTo(x, y);
52:     ctx.quadraticCurveTo(x + rng() * 25 - 12, y + rng() * 25 - 12, x + rng() * 48 - 24, y + rng() * 48 - 24);
53:     ctx.stroke();
54:   }
55:   const texture = new THREE.CanvasTexture(canvas);
56:   texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
57:   texture.colorSpace = THREE.SRGBColorSpace;
58:   texture.anisotropy = 4;
59:   return texture;
60: }
