62: function makeRadialTexture(inner = "rgba(255,255,255,1)", outer = "rgba(255,255,255,0)", size = 128) {
63:   const canvas = document.createElement("canvas");
64:   canvas.width = size;
65:   canvas.height = size;
66:   const ctx = canvas.getContext("2d");
67:   const grad = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
68:   grad.addColorStop(0, inner);
69:   grad.addColorStop(0.3, inner);
70:   grad.addColorStop(1, outer);
71:   ctx.fillStyle = grad;
72:   ctx.fillRect(0, 0, size, size);
73:   const texture = new THREE.CanvasTexture(canvas);
74:   texture.colorSpace = THREE.SRGBColorSpace;
75:   return texture;
76: }
