78: function makeGroundClearingTexture() {
79:   const size = 256;
80:   const canvas = document.createElement("canvas");
81:   canvas.width = size;
82:   canvas.height = size;
83:   const ctx = canvas.getContext("2d");
84:   const grad = ctx.createRadialGradient(size / 2, size / 2, size * 0.08, size / 2, size / 2, size * 0.5);
85:   grad.addColorStop(0, "rgba(111, 112, 73, 0.52)");
86:   grad.addColorStop(0.58, "rgba(98, 101, 66, 0.34)");
87:   grad.addColorStop(0.85, "rgba(78, 86, 58, 0.09)");
88:   grad.addColorStop(1, "rgba(78, 86, 58, 0)");
89:   ctx.fillStyle = grad;
90:   ctx.fillRect(0, 0, size, size);
91:   const rng = mulberry32(41);
92:   for (let i = 0; i < 130; i += 1) {
93:     const x = rng() * size;
94:     const y = rng() * size;
95:     ctx.fillStyle = `rgba(180, 170, 125, ${rng() * 0.06})`;
96:     ctx.beginPath();
97:     ctx.arc(x, y, rng() * 2.5, 0, Math.PI * 2);
98:     ctx.fill();
99:   }
100:   const texture = new THREE.CanvasTexture(canvas);
101:   texture.colorSpace = THREE.SRGBColorSpace;
102:   return texture;
103: }
