220:   buildIsland() {
221:     const group = new THREE.Group();
222:     this.root.add(group);
223:     this.island = group;
224: 
225:     // Top soil mesh, built as a radial grid so the rim can ripple organically.
226:     const rings = 30;
227:     const segments = 128;
228:     const radius = 10.45;
229:     const positions = [];
230:     const colors = [];
231:     const uvs = [];
232:     const indices = [];
233:     const color = new THREE.Color();
234:     const rng = mulberry32(9);
235: 
236:     // center
237:     positions.push(0, terrainHeight(0, 0), 0);
238:     color.setHSL(0.23 + rng() * 0.018, 0.28, 0.31);
239:     colors.push(color.r, color.g, color.b);
240:     uvs.push(0.5, 0.5);
241: 
242:     for (let ring = 1; ring <= rings; ring += 1) {
243:       const rr = (ring / rings) * radius;
244:       for (let s = 0; s < segments; s += 1) {
245:         const a = (s / segments) * Math.PI * 2;
246:         const wobble = 1 + Math.sin(a * 5 + 1.2) * 0.012 + Math.sin(a * 9 - 2) * 0.006;
247:         const x = Math.cos(a) * rr * wobble;
248:         const z = Math.sin(a) * rr * wobble;
249:         const y = terrainHeight(x, z);
250:         positions.push(x, y, z);
251:         const clearing = 1 - smooth(1.8, 4.2, Math.hypot(x, z));
252:         const moisture = 1 - smooth(2.0, 4.4, Math.hypot(x - POND.x, z - POND.z));
253:         const rim = smooth(8.8, 10.4, rr);
254:         color.setHSL(
255:           0.205 + Math.sin(x * 0.82 + z * 0.4) * 0.018 + clearing * 0.018,
256:           0.24 + moisture * 0.13 - rim * 0.09,
257:           0.265 + Math.sin(z * 0.7) * 0.02 + clearing * 0.055 + rim * 0.012,
258:         );
259:         colors.push(color.r, color.g, color.b);
260:         uvs.push(x / (radius * 2) + 0.5, z / (radius * 2) + 0.5);
261:       }
262:     }
263: 
264:     for (let s = 0; s < segments; s += 1) {
265:       indices.push(0, 1 + ((s + 1) % segments), 1 + s);
266:     }
267:     for (let ring = 1; ring < rings; ring += 1) {
268:       const rowA = 1 + (ring - 1) * segments;
269:       const rowB = 1 + ring * segments;
270:       for (let s = 0; s < segments; s += 1) {
271:         const next = (s + 1) % segments;
272:         const a = rowA + s;
273:         const b = rowA + next;
274:         const c = rowB + s;
275:         const d = rowB + next;
276:         indices.push(a, b, c, b, d, c);
277:       }
278:     }
279: 
280:     const geometry = new THREE.BufferGeometry();
281:     geometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
282:     geometry.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
283:     geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
284:     geometry.setIndex(indices);
285:     geometry.computeVertexNormals();
