290:       map: terrainMap,
291:       vertexColors: true,
292:       roughness: 0.96,
293:       metalness: 0,
294:     });
295:     const terrain = new THREE.Mesh(geometry, terrainMaterial);
296:     terrain.receiveShadow = true;
297:     group.add(terrain);
