317:     // Thick rocky underside.
318:     const rimGeo = new THREE.CylinderGeometry(radius, 9.82, 1.35, 96, 2, false);
319:     const rimMat = new THREE.MeshStandardMaterial({ color: 0x26322d, roughness: 0.92, metalness: 0.04 });
320:     const rim = new THREE.Mesh(rimGeo, rimMat);
321:     rim.position.y = -0.675;
322:     rim.receiveShadow = true;
323:     rim.castShadow = true;
324:     group.add(rim);
