369:     const tickMaterial = new THREE.MeshBasicMaterial({ color: 0xa9ffe1, transparent: true, opacity: 0.36 });
370:     for (let i = 0; i < 32; i += 1) {
371:       const a = (i / 32) * Math.PI * 2;
372:       const tick = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.012, i % 4 === 0 ? 0.34 : 0.16), tickMaterial);
373:       tick.position.set(Math.cos(a) * (radius + 0.35), 0.01, Math.sin(a) * (radius + 0.35));
374:       tick.rotation.y = -a + Math.PI / 2;
