381:   addRocks(group) {
382:     const rng = mulberry32(32);
383:     const rockMatA = new THREE.MeshStandardMaterial({ color: 0x59655e, roughness: 0.93, flatShading: true });
384:     const rockMatB = new THREE.MeshStandardMaterial({ color: 0x3b4b43, roughness: 0.97, flatShading: true });
385:     const mossMat = new THREE.MeshStandardMaterial({ color: 0x527449, roughness: 1, flatShading: true });
386:     const rockGeo = new THREE.DodecahedronGeometry(1, 0);
387: 
388:     for (let i = 0; i < 34; i += 1) {
389:       const angle = rng() * Math.PI * 2;
390:       const nearRim = rng() > 0.22;
391:       const rr = nearRim ? 8.1 + rng() * 2.0 : 3.6 + rng() * 4.1;
392:       const x = Math.cos(angle) * rr;
393:       const z = Math.sin(angle) * rr;
394:       if (Math.hypot(x - POND.x, z - POND.z) < POND.radius + 0.35) continue;
395:       const s = nearRim ? 0.2 + rng() * 0.72 : 0.16 + rng() * 0.52;
396:       const rock = new THREE.Mesh(rockGeo, rng() > 0.42 ? rockMatA : rockMatB);
397:       rock.scale.set(s * (0.9 + rng() * 0.5), s * (0.52 + rng() * 0.38), s);
398:       rock.position.set(x, terrainHeight(x, z) + s * 0.18, z);
399:       rock.rotation.set(rng() * 2, rng() * 6, rng() * 2);
400:       rock.castShadow = true;
401:       rock.receiveShadow = true;
402:       group.add(rock);
403: 
404:       if (rng() > 0.48) {
405:         const moss = new THREE.Mesh(new THREE.IcosahedronGeometry(1, 0), mossMat);
406:         moss.scale.set(s * 0.72, s * 0.1, s * 0.58);
407:         moss.position.set(x + rng() * 0.1, rock.position.y + s * 0.35, z + rng() * 0.1);
408:         moss.rotation.y = rng() * 6;
409:         group.add(moss);
410:       }
411:     }
412: 
413:     // Larger stones frame the habitat edge.
414:     const anchorPositions = [
415:       [-7.8, -6.0, 1.1],
416:       [7.2, -6.8, 1.35],
417:       [8.8, 2.1, 0.9],
418:       [-8.5, 4.7, 1.0],
419:       [4.6, 7.2, 0.85],
