421:     for (const [x, z, s] of anchorPositions) {
422:       const rock = new THREE.Mesh(rockGeo, rockMatB);
423:       rock.scale.set(s * 1.4, s * 0.85, s);
424:       rock.position.set(x, terrainHeight(x, z) + s * 0.28, z);
425:       rock.rotation.set(rng() * 1.2, rng() * 6, rng() * 1.2);
