545:     grass.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
546:     const dummy = new THREE.Object3D();
547:     const color = new THREE.Color();
548:     let placed = 0;
549:     let guard = 0;
550:     while (placed < count && guard < count * 14) {
551:       guard += 1;
552:       const a = rng() * Math.PI * 2;
553:       const rr = Math.sqrt(rng()) * 9.7;
554:       const x = Math.cos(a) * rr;
555:       const z = Math.sin(a) * rr;
556:       const pondD = Math.hypot(x - POND.x, z - POND.z);
557:       if (pondD < POND.radius * 1.12) continue;
558:       if (Math.hypot(x, z) < 2.2) continue;
559:       const clearing = smooth(2.2, 4.3, Math.hypot(x, z));
560:       if (rng() > 0.22 + clearing * 0.78) continue;
561:       const scale = 0.55 + rng() * 1.25 + clearing * 0.35;
562:       dummy.position.set(x, terrainHeight(x, z) - 0.01, z);
563:       dummy.rotation.set((rng() - 0.5) * 0.25, rng() * Math.PI * 2, (rng() - 0.5) * 0.24);
564:       dummy.scale.set(0.7 + rng() * 0.7, scale, 0.7 + rng() * 0.7);
565:       dummy.updateMatrix();
566:       grass.setMatrixAt(placed, dummy.matrix);
567:       color.setHSL(0.2 + rng() * 0.05, 0.25 + rng() * 0.24, 0.28 + rng() * 0.16);
568:       grass.setColorAt(placed, color);
569:       placed += 1;
570:     }
571:     grass.count = placed;
572:     grass.receiveShadow = true;
573:     group.add(grass);
574:   }
