939:   updateBursts(dt) {
940:     for (let i = this.bursts.length - 1; i >= 0; i -= 1) {
941:       const burst = this.bursts[i];
942:       burst.age += dt;
943:       for (const particle of burst.particles) {
944:         particle.vy -= dt * 1.7;
945:         particle.mesh.position.x += particle.vx * dt;
946:         particle.mesh.position.y += particle.vy * dt;
947:         particle.mesh.position.z += particle.vz * dt;
948:         particle.mesh.material.opacity = Math.max(0, 0.9 * (1 - burst.age / burst.duration));
949:       }
950:       if (burst.age >= burst.duration) {
951:         burst.group.traverse((obj) => {
952:           if (obj.geometry) obj.geometry.dispose();
953:           if (obj.material) obj.material.dispose();
954:         });
955:         this.scene.remove(burst.group);
956:         this.bursts.splice(i, 1);
957:       }
958:     }
959:   }
