961:   applyEnvironment(env, instant = false) {
962:     this.environment = env;
963:     const climate = env.climate;
964:     const targetKey = climate === 0 ? 0xd8efff : climate === 2 ? 0xffd3a0 : 0xffe7c2;
965:     const targetHemi = climate === 0 ? 0xa8ddff : climate === 2 ? 0xffd6a1 : 0x9be2c9;
966:     const targetFill = climate === 0 ? 0x7bc4ff : climate === 2 ? 0xffa25e : 0x62d8ff;
967:     const targetFog = climate === 0 ? 0x09181b : climate === 2 ? 0x1a130d : 0x071612;
968: 
969:     if (instant) {
970:       this.keyLight.color.setHex(targetKey);
971:       this.hemi.color.setHex(targetHemi);
972:       this.fillLight.color.setHex(targetFill);
973:       this.scene.fog.color.setHex(targetFog);
974:       this.scene.fog.density = climate === 0 ? 0.019 : climate === 2 ? 0.021 : 0.016;
975:       this.keyLight.intensity = climate === 0 ? 1.9 : climate === 2 ? 2.55 : 2.35;
976:       this.water.material.color.setHex(climate === 0 ? 0x0a3a4e : climate === 2 ? 0x194c45 : 0x0a4650);
977:     } else {
978:       this.environmentLerp = {
979:         key: new THREE.Color(targetKey),
980:         hemi: new THREE.Color(targetHemi),
981:         fill: new THREE.Color(targetFill),
982:         fog: new THREE.Color(targetFog),
983:       };
984:     }
985: 
986:     for (const fruit of this.fruits) {
987:       fruit.visible = env.food > 0;
988:       fruit.scale.setScalar(env.food === 2 ? 1.35 : env.food === 1 ? 1 : 0.72);
989:     }
990: 
991:     const eyeStrength = [0.0, 0.65, 1][env.predators];
992:     for (let i = 0; i < this.predatorEyes.length; i += 1) {
993:       const pair = this.predatorEyes[i];
994:       pair.visible = eyeStrength > 0;
995:       pair.userData.targetScale = eyeStrength * (i % 2 === 0 ? 1 : 0.82);
996:     }
