1034:   updateEnvironmentLerp(dt) {
1035:     if (!this.environmentLerp) return;
1036:     const k = 1 - Math.exp(-dt * 1.5);
1037:     this.keyLight.color.lerp(this.environmentLerp.key, k);
1038:     this.hemi.color.lerp(this.environmentLerp.hemi, k);
1039:     this.fillLight.color.lerp(this.environmentLerp.fill, k);
1040:     this.scene.fog.color.lerp(this.environmentLerp.fog, k);
1041:     const climate = this.environment.climate;
