785:   select(index, updateFocus = true) {
786:     this.selectedIndex = Math.max(0, Math.min(this.creatures.length - 1, index));
787:     const creature = this.creatures[this.selectedIndex];
788:     if (!creature) return null;
789:     if (updateFocus) {
790:       this.world.setSelection(creature.position, creature.radius);
