795:   replace(index, organism) {
796:     const old = this.creatures[index];
797:     if (!old) return null;
798:     const position = old.position.clone();
799:     const wasSelected = this.selectedIndex === index;
800:     old.dispose();
801:     const creature = new Creature({
802:       genome: organism.genome,
803:       evaluation: organism.evaluation,
804:       world: this.world,
805:       rng: mulberry32(7103 + index * 193 + organism.id * 7),
806:       index,
807:       position,
808:       stage: old.stage,
809:     });
810:     organism.creature = creature;
811:     this.creatures[index] = creature;
812:     if (wasSelected) this.select(index);
