840:     this.pointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
841:     this.pointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
842:     this.raycaster.setFromCamera(this.pointer, this.world.camera);
843:     const hits = this.raycaster.intersectObjects(this.world.lifeGroup.children, true);
844:     if (!hits.length) return null;
845:     let node = hits[0].object;
