35: export function mulberry32(seed) {
36:   let a = seed >>> 0;
37:   return function random() {
38:     a |= 0;
39:     a = (a + 0x6d2b79f5) | 0;
40:     let t = Math.imul(a ^ (a >>> 15), 1 | a);
41:     t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
42:     return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
43:   };
