112: export function evaluate(genome, env, condition = 1) {
113:   const g = genome;
114:   const sizeTarget = [0.76, 0.49, 0.26][env.climate];
115:   const fatTarget = [0.72, 0.34, 0.1][env.climate];
116:   const legTarget = [0.36, 0.5, 0.73][env.climate];
117: 
118:   let thermal =
119:     1 -
120:     Math.abs(g.bodySize - sizeTarget) * 1.28 -
121:     Math.abs(g.fat - fatTarget) * 1.06 -
122:     Math.abs(g.legs - legTarget) * 0.34;
123:   if (env.climate === 0) thermal += g.armor * 0.025;
124:   thermal = clamp01(thermal + 0.04);
125: 
126:   let foraging;
127:   if (env.food === 0) {
128:     foraging = 0.08 + g.neck * 0.58 + g.legs * 0.21 + (1 - g.bodySize) * 0.12;
129:   } else if (env.food === 1) {
130:     foraging = 0.48 + (1 - Math.abs(g.neck - 0.44)) * 0.2 + (1 - Math.abs(g.bodySize - 0.5)) * 0.16 + g.legs * 0.1;
131:   } else {
132:     foraging = 0.58 + g.bodySize * 0.2 + g.fat * 0.08 + (1 - Math.abs(g.neck - 0.35)) * 0.12;
133:   }
134:   foraging = clamp01(foraging);
135: 
136:   const evasion = clamp01(0.08 + g.legs * 0.38 + g.speed * 0.42 + g.tail * 0.07);
137:   const defense = clamp01(g.armor * 0.58 + g.bodySize * 0.16 + g.fat * 0.09 + g.crest * 0.08 + evasion * 0.15);
138:   const protection = clamp01(defense * 0.57 + evasion * 0.57);
139:   const efficiency = clamp01(1.08 - (g.bodySize * 0.19 + g.armor * 0.23 + g.fat * 0.15 + g.speed * 0.11) + env.food * 0.055);
140: 
141:   const weights = {
142:     thermal: 0.18 + (env.climate === 1 ? 0.035 : 0.17),
143:     foraging: 0.17 + (env.food === 1 ? 0.035 : 0.15),
144:     defense: 0.1 + [0.02, 0.14, 0.22][env.predators],
145:     efficiency: 0.18 + (env.food === 0 ? 0.07 : 0),
146:   };
147:   const total = Object.values(weights).reduce((sum, value) => sum + value, 0);
148:   const weighted =
149:     (thermal * weights.thermal +
150:       foraging * weights.foraging +
151:       protection * weights.defense +
152:       efficiency * weights.efficiency) /
153:     total;
154: 
155:   return {
156:     fitness: Math.max(1, Math.min(99, weighted * 100 * condition)),
157:     components: {
158:       thermal: thermal * 100,
159:       foraging: foraging * 100,
160:       defense: protection * 100,
161:       efficiency: efficiency * 100,
162:     },
163:     weights,
164:   };
165: }
