260: export function diversity(population) {
261:   if (population.length < 2) return 0;
262:   let sum = 0;
263:   let count = 0;
264:   for (let i = 0; i < population.length; i += 1) {
265:     for (let j = i + 1; j < population.length; j += 1) {
266:       let d = 0;
267:       for (const key of GENE_KEYS) {
268:         d += Math.abs(population[i].genome[key] - population[j].genome[key]);
269:       }
270:       sum += d / GENE_KEYS.length;
271:       count += 1;
272:     }
273:   }
274:   return sum / count;
275: }
