281: export function breedPopulation(population, env, rng = Math.random) {
282:   const ranked = rankPopulation(population);
283:   const eliteCount = Math.max(2, Math.round(population.length * 0.34));
284:   const parents = ranked.slice(0, Math.max(3, eliteCount));
285:   const next = [];
286: 
287:   // A true survivor keeps its exact alleles and becomes the first hatchling.
288:   next.push({ genome: { ...parents[0].genome }, origin: "elite", changes: [] });
289: 
290:   while (next.length < population.length) {
291:     const a = weightedParent(parents, rng);
292:     let b = weightedParent(parents, rng);
293:     if (parents.length > 1) {
294:       let guard = 0;
295:       while (b === a && guard < 8) {
296:         b = weightedParent(parents, rng);
297:         guard += 1;
298:       }
299:     }
300:     let genome = a === b ? { ...a.genome } : crossover(a.genome, b.genome, rng);
301:     const mutation = mutate(genome, rng, next.length === 1 ? 0.08 : 0.18, 0.1);
302:     genome = mutation.genome;
303:     next.push({
304:       genome,
305:       origin: next.length === 1 ? "elite-mutant" : "offspring",
306:       changes: mutation.changes,
307:       parents: [a.id, b.id],
308:     });
309:   }
310: 
311:   return next;
312: }
