314: function weightedParent(parents, rng) {
315:   const weights = parents.map((p) => Math.pow(Math.max(1, p.evaluation.fitness), 2.4));
316:   const total = weights.reduce((a, b) => a + b, 0);
317:   let roll = rng() * total;
318:   for (let i = 0; i < parents.length; i += 1) {
319:     roll -= weights[i];
320:     if (roll <= 0) return parents[i];
321:   }
322:   return parents[parents.length - 1];
323: }
