node --input-type=module <<'NODE'
const targets = await (await fetch('http://127.0.0.1:9223/json')).json();
const target = targets.find((item) => item.type === 'page');
if (!target) throw new Error('No browser page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, { once: true }); ws.addEventListener('error', reject, { once: true }); });
let id = 0;
const pending = new Map();
const exceptions = [];
ws.addEventListener('message', (event) => {
  const message = JSON.parse(event.data);
  if (message.method === 'Runtime.exceptionThrown') exceptions.push(message.params.exceptionDetails.text);
  if (message.id && pending.has(message.id)) {
    const { resolve, reject } = pending.get(message.id); pending.delete(message.id);
    message.error ? reject(new Error(message.error.message)) : resolve(message.result);
  }
});
const send = (method, params = {}) => new Promise((resolve, reject) => {
  const requestId = ++id; pending.set(requestId, { resolve, reject }); ws.send(JSON.stringify({ id: requestId, method, params }));
});
await send('Runtime.enable');
await send('Page.enable');
await new Promise((resolve) => setTimeout(resolve, 3000));
const result = await send('Runtime.evaluate', { awaitPromise: true, returnByValue: true, expression: `(() => {
 const h = window.__helix;
 if (!h) return { error: 'game API not initialized' };
 const checks = [];
 checks.push(['founders', h.state.population.length === 6 && document.querySelector('#stat-population').textContent.trim() === '06']);
 h.selectIndex(2, false); checks.push(['selection', h.creatures.selectedIndex === 2]);
 const reserve = h.state.mutagen; h.directMutation('neck'); checks.push(['direct mutation', h.state.mutagen === reserve - 1]);
 h.setEnvironment('climate', 2); checks.push(['environment', h.state.env.climate === 2 && document.querySelector('#climate-readout').textContent.trim() === 'Arid']);
 h.advanceGeneration(); checks.push(['generation advance', h.state.generation === 2 && h.state.population.length === 6]);
 h.resetStudy(); checks.push(['reset', h.state.generation === 1 && h.state.env.climate === 1 && h.state.mutagen === 3]);
 return { checks, generation: document.querySelector('#stat-generation').textContent.trim(), population: document.querySelector('#stat-population').textContent.trim(), specimen: document.querySelector('#specimen-name').textContent.trim() };
})()` });
const screenshot = await send('Page.captureScreenshot', { format: 'jpeg', quality: 78, captureBeyondViewport: false });
await import('node:fs/promises').then(({ writeFile }) => writeFile('/tmp/opencode/helix-check.jpg', Buffer.from(screenshot.data, 'base64')));
console.log(JSON.stringify({ result: result.result.value, exceptions, screenshot: '/tmp/opencode/helix-check.jpg' }, null, 2));
ws.close();
